from pathlib import Path
import base64,hashlib,importlib.machinery,json,os,struct,subprocess,sys
R=Path.cwd();D=R/'.tools/runtime5-request-env-paired';O=R/'.tools/review7-request-source';O.mkdir(exist_ok=False);sys.path.insert(0,str(D/'tests/semantics'));import static_types as t
observer=importlib.machinery.SourceFileLoader('review7_request_observer',str(D/'bin/php-semantics')).load_module();M=D/'frozen-review-inputs.json';m=json.loads(M.read_text())
def verify():
 for p,h in m['files'].items():assert hashlib.sha256((D/p).read_bytes()).hexdigest()==h,p
verify();original=D/'.tools/request-source-nivqyati/originals.json';rows=json.loads(original.read_text())['records'];assert len(rows)==246;records=[];failures=[]
f=t.Worker([str(D/'.tools/php/bin/php'),'-n',*t.FLAGS,'-d','extension='+str(D/'.tools/php-file.so'),str(D/'frontend/worker.php')]);a=t.Worker([str(D/'_build/default/adapter/main.exe'),str(D)])
try:
 for i,row in enumerate(rows):
  p=Path(row['context']);source=base64.b64decode(row['source_base64']);assert p.read_bytes()==source;req=row['request'];entries=[base64.b64decode(k)+b'='+base64.b64decode(v) for k,v in req['env']];packet=b'PHPRQ001'+struct.pack('<qII',int(req['seconds']),req['microseconds'],len(entries))+b''.join(struct.pack('<I',len(e))+e for e in entries);payload=O/f'case-{i:03}.input';payload.write_bytes(packet);assert hashlib.sha256(packet).hexdigest()==row['payload_sha256'];cmd=row['oracle']['command']
  with payload.open('rb') as stream:
   os.dup2(stream.fileno(),198)
   try:native=subprocess.run(cmd,env={'LD_PRELOAD':str(D/'.tools/request-clock.so')},pass_fds=(198,),cwd=p.parent,capture_output=True,timeout=20)
   finally:os.close(198)
  oracle={'stdout':base64.b64encode(native.stdout).decode(),'stderr':base64.b64encode(native.stderr).decode(),'exit_status':native.returncode};assert all(oracle[k]==row['oracle'][k] for k in oracle),row['id'];parsed=f.request({'op':'parse','source':row['source_base64']});assert parsed['accepted'],(row['id'],parsed);checked=a.request({'op':'check','ast':parsed['ast'],'fixture':True});response=a.request({'op':'execute','ast':parsed['ast'],'steps':10000,'filename':base64.b64encode(str(p).encode()).decode(),'request':req});record={**row,'oracle':oracle,'parsed':parsed,'checked':checked,'response':response}
  if response.get('ok') is True:
   actual=observer.observe(response['state'],str(p));record['actual']=actual;record['agrees']=actual['status'] in ('normal','php_error','static_rejection') and all(actual[k]==oracle[k] for k in oracle)
  else:record['agrees']=False
  records.append(record);(O/f'case-{i:03}.json').write_text(json.dumps(record,indent=2)+'\n')
  if not record['agrees']:failures.append(row['id']);print('FAIL',row['id'],record.get('actual',response),flush=True)
  if i%20==0:print(i+1,'reviewed',len(failures),'failures',flush=True)
finally:f.close();a.close()
verify();report={'result':'pass' if not failures else 'fail','scope':'Independent246 fresh exact native/provider and checked source comparisons on frozen840 request/GLOBALS candidate; no canonical admission. Unsupported and tool failures never agree.','manifest_sha256':hashlib.sha256(M.read_bytes()).hexdigest(),'originals_sha256':hashlib.sha256(original.read_bytes()).hexdigest(),'records':records,'failures':failures};(O/'review.json').write_text(json.dumps(report,indent=2)+'\n');print(len(records),'sources',report['result'],failures);assert not failures
